using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace OneMoreTime.EditorTools {
public static class AnimationGalleryBuilder {
 [MenuItem("Tools/One More Time/Open Animation Gallery")]
 public static void Open(){if(EditorApplication.isPlaying)throw new System.Exception("Stop Play first");var path=DemoBuilder.Root+"/Scenes/Dev_AnimationGallery.unity";DemoBuilder.BackupScene(path);var previous=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var existing=UnityEngine.SceneManagement.SceneManager.GetSceneByPath(path);bool wasLoaded=existing.IsValid()&&existing.isLoaded;var scene=wasLoaded?existing:System.IO.File.Exists(path)?EditorSceneManager.OpenScene(path,OpenSceneMode.Additive):EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);UnityEngine.SceneManagement.SceneManager.SetActiveScene(scene);foreach(var candidate in scene.GetRootGameObjects())if(candidate.name=="OMT Managed")UnityEngine.Object.DestroyImmediate(candidate);var root=new GameObject("OMT Managed");var gallery=root.AddComponent<AnimationGallery>();gallery.font=PresentationBuilder.Font;gallery.actors=new PlayerVisual[6];var goat=AssetDatabase.LoadAssetAtPath<AnimationLibrary>(DemoBuilder.Root+"/Config/AnimationLibrary.asset");var fox=AssetDatabase.LoadAssetAtPath<AnimationLibrary>(DemoBuilder.Root+"/Config/FoxAnimationLibrary.asset");for(int i=0;i<6;i++){var g=new GameObject("Pose "+i);g.transform.SetParent(root.transform);var v=g.AddComponent<PlayerVisual>();v.library=i==5?fox:goat;var image=new GameObject("Sprite");image.transform.SetParent(g.transform);v.renderer2D=image.AddComponent<SpriteRenderer>();gallery.actors[i]=v;}
 var camera=new GameObject("Camera").AddComponent<Camera>();camera.transform.SetParent(root.transform);camera.orthographic=true;camera.orthographicSize=5.5f;camera.transform.position=new Vector3(0,1,-10);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.05f,.13f,.12f);EditorSceneManager.SaveScene(scene,path);if(!wasLoaded)EditorSceneManager.CloseScene(scene,true);UnityEngine.SceneManagement.SceneManager.SetActiveScene(previous);if(wasLoaded)UnityEngine.SceneManagement.SceneManager.SetActiveScene(scene);else EditorSceneManager.OpenScene(path);}
}
}
